import { randomUUID } from "node:crypto";
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
import { countQuotaUsage } from "@/lib/delivery-usage";
import { PrismaPg } from "@prisma/adapter-pg";
import { PrismaClient } from "@/generated/prisma/client";
import type { EntitlementUser } from "@/lib/entitlements";
import { resolveUsagePeriods, type UsagePeriods } from "@/lib/usage-periods";
import {
  claimUsage,
  confirmUsage,
  ensureUsagePeriods,
  importUsageEvidence,
  markUsageUncertain,
  rebindUsage,
  releaseUsage,
  reserveUsage,
  withUsageTransaction,
  type UsageOwnerTransaction,
} from "@/lib/usage-ledger";
import {
  createIsolatedDatabase,
  databaseTestsEnabled,
} from "./helpers/foundation-db";

const now = new Date("2026-10-16T12:00:00Z");
const free: EntitlementUser = {
  id: randomUUID(),
  plan: "FREE",
  subscriptionStatus: "NONE",
  dodoSubscriptionId: null,
  currentPeriodStart: null,
  currentPeriodEnd: null,
  gracePeriodEnd: null,
  planOverride: null,
  planOverrideStartsAt: null,
  planOverrideExpiresAt: null,
  grandfatheredUntil: null,
  isSuspended: false,
  deletionRequestedAt: null,
  gmailAuthorized: true,
};
const paid: EntitlementUser = {
  ...free,
  plan: "PAID",
  subscriptionStatus: "ACTIVE",
  dodoSubscriptionId: "provider-sub",
  currentPeriodStart: new Date("2026-10-10T03:04:05.678Z"),
  currentPeriodEnd: new Date("2026-11-10T03:04:05.678Z"),
};

describe("usage period resolution", () => {
  it("uses half-open UTC days and calendar months at leap, month and year boundaries", () => {
    for (const [at, dayStart, dayEnd, monthEnd] of [
      ["2028-02-29T23:59:59.999Z", "2028-02-29", "2028-03-01", "2028-03-01"],
      ["2026-12-31T23:59:59.999Z", "2026-12-31", "2027-01-01", "2027-01-01"],
      ["2027-01-01T00:00:00Z", "2027-01-01", "2027-01-02", "2027-02-01"],
    ]) {
      const periods = resolveUsagePeriods(free, new Date(at));
      expect(periods.daily.startsAt.toISOString()).toBe(
        `${dayStart}T00:00:00.000Z`,
      );
      expect(periods.daily.endsAt.toISOString()).toBe(
        `${dayEnd}T00:00:00.000Z`,
      );
      expect(periods.monthly.endsAt.toISOString()).toBe(
        `${monthEnd}T00:00:00.000Z`,
      );
      expect([periods.daily.limit, periods.monthly.limit]).toEqual([3, 15]);
    }
    expect(
      resolveUsagePeriods(free, new Date("2026-10-17T05:29:59+05:30")).daily
        .key,
    ).toBe(resolveUsagePeriods(free, now).daily.key);
  });
  it("shares daily identity across plans and uses exact provider boundaries", () => {
    const a = resolveUsagePeriods(free, now),
      b = resolveUsagePeriods(paid, now);
    expect(a.daily.key).toBe(b.daily.key);
    expect(b.monthly.startsAt).toEqual(paid.currentPeriodStart);
    expect(b.monthly.endsAt).toEqual(paid.currentPeriodEnd);
    expect([b.daily.limit, b.monthly.limit]).toEqual([20, 300]);
    expect(
      resolveUsagePeriods({ ...paid, dodoSubscriptionId: "another" }, now)
        .monthly.key,
    ).not.toBe(b.monthly.key);
  });
  it("uses calendar months for complimentary access, retaining real provider periods", () => {
    const grant = {
      planOverride: "PAID" as const,
      planOverrideStartsAt: new Date("2026-01-01"),
    };
    const a = resolveUsagePeriods({ ...free, ...grant }, now);
    expect(a.monthly.key).toBe(resolveUsagePeriods(free, now).monthly.key);
    expect(a.monthly.limit).toBe(300);
    expect(resolveUsagePeriods({ ...paid, ...grant }, now).monthly.key).toBe(
      resolveUsagePeriods(paid, now).monthly.key,
    );
    expect(
      resolveUsagePeriods(
        { ...free, grandfatheredUntil: new Date("2027-01-01") },
        now,
      ).monthly.key,
    ).toBe(a.monthly.key);
    expect(
      resolveUsagePeriods(
        { ...free, ...grant, planOverrideExpiresAt: now },
        now,
      ).daily.limit,
    ).toBe(3);
  });
  it("extends grace without issuing a new allowance, and pauses unresolved provider state", () => {
    const grace = {
      ...paid,
      subscriptionStatus: "PAST_DUE" as const,
      gracePeriodEnd: new Date("2026-11-13T03:04:05.678Z"),
    };
    const a = resolveUsagePeriods(paid, now).monthly;
    const b = resolveUsagePeriods(grace, new Date("2026-11-11")).monthly;
    expect(a.key).toBe(b.key);
    expect(b.endsAt).toEqual(a.endsAt);
    expect(b.operationalEndsAt).toEqual(grace.gracePeriodEnd);
    expect(resolveUsagePeriods(grace, grace.gracePeriodEnd).monthly.limit).toBe(
      15,
    );
    expect(() => resolveUsagePeriods(paid, paid.currentPeriodEnd!)).toThrow(
      "verified",
    );
    expect(() =>
      resolveUsagePeriods({ ...paid, currentPeriodStart: null }, now),
    ).toThrow("verified");
    expect(
      resolveUsagePeriods(
        { ...paid, subscriptionStatus: "EXPIRED" },
        new Date("2026-11-11"),
      ).monthly.key,
    ).toContain("month:");
  });
});

describe.runIf(databaseTestsEnabled)(
  "usage ledger with real PostgreSQL",
  () => {
    let fixture: Awaited<ReturnType<typeof createIsolatedDatabase>>;
    let db: PrismaClient;
    beforeAll(async () => {
      fixture = await createIsolatedDatabase();
      try {
        for (const name of fixture.migrations) await fixture.apply(name);
        db = new PrismaClient({
          adapter: new PrismaPg(
            { connectionString: fixture.url, max: 25 },
            { schema: fixture.schema },
          ),
        });
      } catch (error) {
        await fixture.cleanup();
        throw error;
      }
    });
    afterAll(async () => {
      if (db) await db.$disconnect();
      if (fixture) await fixture.cleanup();
    });

    async function setup(count = 1) {
      const user = await db.user.create({
        data: { email: `${randomUUID()}@example.test` },
      });
      const template = await db.template.create({
        data: { userId: user.id, name: "Fixture", subject: "S", body: "B" },
      });
      const contact = await db.contact.create({
        data: { userId: user.id, name: "Ada", email: "[REDACTED_EMAIL]" },
      });
      const campaign = await db.campaign.create({
        data: { userId: user.id, templateId: template.id, status: "QUEUED" },
      });
      const sends = [];
      for (let i = 0; i < count; i++)
        sends.push(
          await db.send.create({
            data: { campaignId: campaign.id, contactId: contact.id },
          }),
        );
      const specs = resolveUsagePeriods(user, now);
      return {
        user,
        template,
        contact,
        campaign,
        sends,
        specs,
        items: sends.map((s) => ({ sendId: s.id, deliveryKey: s.id })),
      };
    }
    async function totals(userId: string) {
      return db.usagePeriod.findMany({
        where: { userId },
        orderBy: [{ kind: "asc" }, { startsAt: "asc" }, { key: "asc" }],
      });
    }
    async function reserved(
      f: Awaited<ReturnType<typeof setup>>,
      specs = f.specs,
    ) {
      return withUsageTransaction(db, f.user.id, (owner) =>
        reserveUsage(owner, specs, f.items, true),
      );
    }

    it("resets completed test usage while preserving history, queued work, other users, and production limits", async () => {
      const f = await setup(3),
        other = await setup();
      await reserved(f);
      await reserved(other);
      for (const item of f.items.slice(0, 2)) {
        await withUsageTransaction(db, f.user.id, async (owner) => {
          const claim = await claimUsage(
            owner,
            item.deliveryKey,
            f.specs,
            true,
            now,
          );
          await confirmUsage(
            owner,
            item.deliveryKey,
            claim.reservation.claimToken!,
            {
              gmailMessageId: item.sendId,
              sentAt: now,
            },
          );
        });
      }
      const resetAt = new Date(+now + 1000);
      await db.user.update({
        where: { id: f.user.id },
        data: { testingUsageResetAt: resetAt },
      });
      try {
        vi.stubEnv("NODE_ENV", "development");
        const buckets = await withUsageTransaction(db, f.user.id, (owner) =>
          ensureUsagePeriods(owner, f.specs),
        );
        expect([
          buckets.daily.sent,
          buckets.daily.reserved,
          buckets.monthly.sent,
          buckets.monthly.reserved,
        ]).toEqual([0, 1, 0, 1]);
        expect(await countQuotaUsage(f.user.id, db, resetAt)).toBe(1);
        expect(
          await db.send.count({
            where: { campaign: { userId: f.user.id }, status: "SENT" },
          }),
        ).toBe(2);
        expect((await totals(other.user.id)).map((p) => p.reserved)).toEqual([
          1, 1,
        ]);
        await withUsageTransaction(db, f.user.id, async (owner) => {
          const claim = await claimUsage(
            owner,
            f.items[2].deliveryKey,
            f.specs,
            true,
            resetAt,
          );
          await confirmUsage(
            owner,
            f.items[2].deliveryKey,
            claim.reservation.claimToken!,
            {
              gmailMessageId: "after-reset",
              sentAt: new Date(+resetAt + 1),
            },
          );
        });
        expect(
          (await totals(f.user.id)).map((p) => [p.sent, p.reserved]),
        ).toEqual([
          [1, 0],
          [1, 0],
        ]);
        expect(
          await countQuotaUsage(f.user.id, db, new Date(+resetAt + 2)),
        ).toBe(1);
        vi.stubEnv("NODE_ENV", "production");
        const restored = await withUsageTransaction(db, f.user.id, (owner) =>
          ensureUsagePeriods(owner, f.specs),
        );
        expect([restored.daily.sent, restored.monthly.sent]).toEqual([3, 3]);
        expect(
          await countQuotaUsage(f.user.id, db, new Date(+resetAt + 2)),
        ).toBe(3);
      } finally {
        vi.unstubAllEnvs();
      }
    });

    it("generates UUIDs, reserves idempotently, enforces the owner context and rolls back failed batches", async () => {
      const f = await setup(2);
      const rows = await reserved(f);
      expect((await reserved(f)).map((r) => r.id)).toEqual(
        rows.map((r) => r.id),
      );
      for (const row of [...rows, ...(await totals(f.user.id))])
        expect(row.id).toMatch(/^[0-9a-f-]{36}$/);
      expect(
        (await totals(f.user.id)).map((p) => [p.sent, p.reserved]),
      ).toEqual([
        [0, 2],
        [0, 2],
      ]);
      await expect(
        ensureUsagePeriods(
          { tx: db, userId: f.user.id } as unknown as UsageOwnerTransaction,
          f.specs,
        ),
      ).rejects.toThrow("locked owner");
      const other = await setup();
      await expect(
        withUsageTransaction(db, other.user.id, (owner) =>
          reserveUsage(owner, other.specs, f.items, true),
        ),
      ).rejects.toThrow("send unavailable");
      expect(await totals(other.user.id)).toEqual([]);
      await expect(
        withUsageTransaction(db, f.user.id, async (owner) => {
          const campaign = await owner.tx.campaign.create({
            data: {
              userId: f.user.id,
              templateId: f.template.id,
              status: "QUEUED",
            },
          });
          const items = [];
          for (let i = 0; i < 2; i++) {
            const send = await owner.tx.send.create({
              data: { campaignId: campaign.id, contactId: f.contact.id },
            });
            items.push({ sendId: send.id, deliveryKey: send.id });
          }
          await reserveUsage(owner, f.specs, items, true);
        }),
      ).rejects.toMatchObject({ allowance: "DAILY", remaining: 1 });
      expect(await db.campaign.count({ where: { userId: f.user.id } })).toBe(1);
      expect(
        await db.send.count({ where: { campaign: { userId: f.user.id } } }),
      ).toBe(2);
      expect((await totals(f.user.id)).map((p) => p.reserved)).toEqual([2, 2]);
    });

    for (const allowance of ["DAILY", "MONTHLY"] as const)
      it(`admits exactly one of 20 concurrent whole transactions for the final ${allowance} slot`, async () => {
        const f = await setup(0);
        const specs: UsagePeriods = {
          daily: { ...f.specs.daily, limit: allowance === "DAILY" ? 1 : 100 },
          monthly: {
            ...f.specs.monthly,
            limit: allowance === "MONTHLY" ? 1 : 100,
          },
        };
        const results = await Promise.allSettled(
          Array.from({ length: 20 }, () =>
            withUsageTransaction(db, f.user.id, async (owner) => {
              const campaign = await owner.tx.campaign.create({
                data: {
                  userId: f.user.id,
                  templateId: f.template.id,
                  status: "QUEUED",
                },
              });
              const send = await owner.tx.send.create({
                data: { campaignId: campaign.id, contactId: f.contact.id },
              });
              await reserveUsage(
                owner,
                specs,
                [{ sendId: send.id, deliveryKey: send.id }],
                true,
              );
            }),
          ),
        );
        expect(results.filter((r) => r.status === "fulfilled")).toHaveLength(1);
        for (const r of results)
          if (r.status === "rejected")
            expect(r.reason).toMatchObject({ allowance, remaining: 0 });
        expect(await db.campaign.count({ where: { userId: f.user.id } })).toBe(
          2,
        ); // empty fixture plus winner
        expect(
          await db.send.count({ where: { campaign: { userId: f.user.id } } }),
        ).toBe(1);
        expect((await totals(f.user.id)).map((p) => p.reserved)).toEqual([
          1, 1,
        ]);
      });

    it("claims the final slot once, protects an active lease, and settles atomically once", async () => {
      const f = await setup();
      const specs = {
        daily: { ...f.specs.daily, limit: 1 },
        monthly: { ...f.specs.monthly, limit: 1 },
      };
      await reserved(f, specs);
      const attempts = await Promise.all(
        Array.from({ length: 8 }, () =>
          withUsageTransaction(db, f.user.id, (owner) =>
            claimUsage(owner, f.items[0].deliveryKey, specs, true, now),
          ),
        ),
      );
      expect(attempts.filter((r) => r.claimed)).toHaveLength(1);
      const claim = attempts.find((r) => r.claimed)!.reservation;
      expect(claim.claimToken).toMatch(/^[0-9a-f-]{36}$/);
      expect(+claim.leaseExpiresAt! - +now).toBe(120000);
      await withUsageTransaction(db, f.user.id, (owner) =>
        markUsageUncertain(
          owner,
          claim.deliveryKey,
          claim.claimToken!,
          now,
          true,
        ),
      );
      expect(
        await db.usageReservation.findFirst({ where: { userId: f.user.id } }),
      ).toMatchObject({ status: "ATTEMPTING" });
      await expect(
        withUsageTransaction(db, f.user.id, (owner) =>
          confirmUsage(owner, claim.deliveryKey, randomUUID(), {
            gmailMessageId: "accepted",
            sentAt: now,
          }),
        ),
      ).rejects.toThrow("claim mismatch");
      for (let i = 0; i < 2; i++)
        await withUsageTransaction(db, f.user.id, (owner) =>
          confirmUsage(owner, claim.deliveryKey, claim.claimToken!, {
            gmailMessageId: "accepted",
            sentAt: now,
          }),
        );
      expect(
        (await totals(f.user.id)).map((p) => [p.sent, p.reserved]),
      ).toEqual([
        [1, 0],
        [1, 0],
      ]);
      expect(
        await db.send.findFirst({
          where: { id: f.sends[0].id, campaign: { userId: f.user.id } },
        }),
      ).toMatchObject({
        status: "SENT",
        deliveryState: "DONE",
        gmailMessageId: "accepted",
        claimToken: null,
        leaseExpiresAt: null,
      });
      expect(
        (
          await withUsageTransaction(db, f.user.id, (owner) =>
            claimUsage(owner, claim.deliveryKey, specs, true, now),
          )
        ).claimed,
      ).toBe(false);
    });

    it("retains expired or uncertain claims, disallows refunds, and accepts late durable success", async () => {
      const f = await setup();
      await reserved(f);
      const claim = (
        await withUsageTransaction(db, f.user.id, (owner) =>
          claimUsage(owner, f.items[0].deliveryKey, f.specs, true, now),
        )
      ).reservation;
      const later = new Date(+now + 120001);
      for (let i = 0; i < 2; i++)
        await withUsageTransaction(db, f.user.id, (owner) =>
          markUsageUncertain(
            owner,
            claim.deliveryKey,
            claim.claimToken!,
            later,
            true,
          ),
        );
      expect((await totals(f.user.id)).map((p) => p.reserved)).toEqual([1, 1]);
      await expect(
        withUsageTransaction(db, f.user.id, (owner) =>
          releaseUsage(owner, claim.deliveryKey, { kind: "UNSUBMITTED" }),
        ),
      ).rejects.toThrow("proven unsubmitted");
      await expect(
        withUsageTransaction(db, f.user.id, (owner) =>
          releaseUsage(owner, claim.deliveryKey, {
            kind: "DEFINITE_REJECTION",
            claimToken: claim.claimToken!,
          }),
        ),
      ).rejects.toThrow("definite rejection");
      await expect(
        withUsageTransaction(db, f.user.id, (owner) =>
          rebindUsage(owner, claim.deliveryKey, f.specs, true),
        ),
      ).rejects.toThrow("cannot be rebound");
      expect(
        (
          await withUsageTransaction(db, f.user.id, (owner) =>
            claimUsage(owner, claim.deliveryKey, f.specs, true, later),
          )
        ).claimed,
      ).toBe(false);
      await withUsageTransaction(db, f.user.id, (owner) =>
        confirmUsage(owner, claim.deliveryKey, claim.claimToken!, {
          gmailMessageId: "late-accepted",
          sentAt: later,
        }),
      );
      expect(
        (await totals(f.user.id)).map((p) => [p.sent, p.reserved]),
      ).toEqual([
        [1, 0],
        [1, 0],
      ]);
    });

    it("releases proven unsent work once, handles a cancellation/claim race, and rejects over-limit claims", async () => {
      const f = await setup(2);
      await reserved(f);
      const key = f.items[0].deliveryKey;
      const results = await Promise.allSettled([
        withUsageTransaction(db, f.user.id, (owner) =>
          releaseUsage(owner, key, { kind: "UNSUBMITTED" }, now),
        ),
        withUsageTransaction(db, f.user.id, (owner) =>
          claimUsage(owner, key, f.specs, true, now),
        ),
      ]);
      const row = await db.usageReservation.findFirstOrThrow({
        where: { userId: f.user.id, deliveryKey: key },
      });
      if (row.status === "RELEASED") {
        await withUsageTransaction(db, f.user.id, (owner) =>
          releaseUsage(owner, key, { kind: "UNSUBMITTED" }, now),
        );
        expect((await totals(f.user.id)).map((p) => p.reserved)).toEqual([
          1, 1,
        ]);
      } else {
        expect(row.status).toBe("ATTEMPTING");
        expect(results[0].status).toBe("rejected");
        await withUsageTransaction(db, f.user.id, (owner) =>
          releaseUsage(
            owner,
            key,
            { kind: "DEFINITE_REJECTION", claimToken: row.claimToken! },
            now,
          ),
        );
      }
      await expect(
        withUsageTransaction(db, f.user.id, (owner) =>
          claimUsage(
            owner,
            f.items[1].deliveryKey,
            { daily: { ...f.specs.daily, limit: 0 }, monthly: f.specs.monthly },
            true,
            now,
          ),
        ),
      ).rejects.toMatchObject({ allowance: "DAILY" });
      expect(
        await db.usageReservation.findFirst({
          where: { userId: f.user.id, deliveryKey: f.items[1].deliveryKey },
        }),
      ).toMatchObject({ status: "RESERVED", chargedAt: null });
    });

    it("rebinds across midnight/month boundaries only when capacity exists and enforces availability/expiry", async () => {
      const f = await setup();
      const before = new Date("2026-10-31T23:59:59Z"),
        after = new Date("2026-11-01T00:00:01Z");
      const old = resolveUsagePeriods(f.user, before),
        next = resolveUsagePeriods(f.user, after);
      await reserved(f, old);
      await expect(
        withUsageTransaction(db, f.user.id, (owner) =>
          rebindUsage(
            owner,
            f.items[0].deliveryKey,
            { daily: next.daily, monthly: { ...next.monthly, limit: 0 } },
            true,
          ),
        ),
      ).rejects.toMatchObject({ allowance: "MONTHLY" });
      expect((await totals(f.user.id)).map((p) => p.reserved)).toEqual([1, 1]);
      await withUsageTransaction(db, f.user.id, (owner) =>
        rebindUsage(owner, f.items[0].deliveryKey, next, true),
      );
      expect((await totals(f.user.id)).map((p) => p.reserved)).toEqual([
        0, 1, 0, 1,
      ]);
      await db.send.updateMany({
        where: { id: f.sends[0].id, campaign: { userId: f.user.id } },
        data: { availableAt: new Date(+after + 1000) },
      });
      await expect(
        withUsageTransaction(db, f.user.id, (owner) =>
          claimUsage(owner, f.items[0].deliveryKey, next, true, after),
        ),
      ).rejects.toThrow("not available");
      await db.send.updateMany({
        where: { id: f.sends[0].id, campaign: { userId: f.user.id } },
        data: { availableAt: null, queueExpiresAt: after },
      });
      await expect(
        withUsageTransaction(db, f.user.id, (owner) =>
          claimUsage(owner, f.items[0].deliveryKey, next, true, after),
        ),
      ).rejects.toThrow("not available");
      await withUsageTransaction(db, f.user.id, (owner) =>
        releaseUsage(
          owner,
          f.items[0].deliveryKey,
          { kind: "UNSUBMITTED" },
          after,
        ),
      );
      expect((await totals(f.user.id)).every((p) => p.reserved === 0)).toBe(
        true,
      );
    });

    it("seeds historical evidence once, survives history deletion, and charges a live delivery only once per overlapping allowance", async () => {
      const f = await setup();
      await withUsageTransaction(db, f.user.id, async (owner) => {
        const evidence = {
          sourceKey: "receipt:old",
          deliveryKey: randomUUID(),
          chargedAt: now,
          timestampSource: "sentAt" as const,
        };
        const first = await importUsageEvidence(owner, evidence);
        expect((await importUsageEvidence(owner, evidence)).id).toBe(first.id);
      });
      await reserved(f);
      const claim = (
        await withUsageTransaction(db, f.user.id, (owner) =>
          claimUsage(owner, f.items[0].deliveryKey, f.specs, true, now),
        )
      ).reservation;
      const provider = resolveUsagePeriods(paid, now);
      await withUsageTransaction(db, f.user.id, (owner) =>
        ensureUsagePeriods(owner, provider),
      );
      const bucket = () =>
        db.usagePeriod.findFirstOrThrow({
          where: { userId: f.user.id, key: provider.monthly.key },
        });
      expect(await bucket()).toMatchObject({
        sent: 1,
        reserved: 1,
        importedSent: 1,
        importedReserved: 1,
      });
      await withUsageTransaction(db, f.user.id, (owner) =>
        markUsageUncertain(
          owner,
          claim.deliveryKey,
          claim.claimToken!,
          new Date(+now + 120001),
          true,
        ),
      );
      expect(await bucket()).toMatchObject({ sent: 1, reserved: 1 });
      await withUsageTransaction(db, f.user.id, (owner) =>
        confirmUsage(owner, claim.deliveryKey, claim.claimToken!, {
          gmailMessageId: "accepted",
          sentAt: now,
        }),
      );
      expect(await bucket()).toMatchObject({
        sent: 2,
        reserved: 0,
        importedSent: 2,
        importedReserved: 0,
      });
      await withUsageTransaction(db, f.user.id, (owner) =>
        importUsageEvidence(owner, {
