    it("extends one grace bucket and seeds renewal overlap from attempts during grace", async () => {
      const f = await setup();
      const graceUser = {
        ...paid,
        subscriptionStatus: "PAST_DUE" as const,
        gracePeriodEnd: new Date("2026-11-13T03:04:05.678Z"),
      };
      const inGrace = new Date("2026-11-11T12:00:00Z");
      const initial = await withUsageTransaction(db, f.user.id, (owner) =>
        ensureUsagePeriods(owner, resolveUsagePeriods(paid, now)),
      );
      const graceSpecs = resolveUsagePeriods(graceUser, inGrace);
      await reserved(f, graceSpecs);
      const extended = await withUsageTransaction(db, f.user.id, (owner) =>
        ensureUsagePeriods(owner, graceSpecs),
      );
      expect(extended.monthly.id).toBe(initial.monthly.id);
      expect(extended.monthly.operationalEndsAt).toEqual(
        graceUser.gracePeriodEnd,
      );
      const claim = (
        await withUsageTransaction(db, f.user.id, (owner) =>
          claimUsage(owner, f.items[0].deliveryKey, graceSpecs, true, inGrace),
        )
      ).reservation;
      const renewal = resolveUsagePeriods(
        {
          ...paid,
          currentPeriodStart: paid.currentPeriodEnd,
          currentPeriodEnd: new Date("2026-12-10T03:04:05.678Z"),
        },
        inGrace,
      );
      const next = await withUsageTransaction(db, f.user.id, (owner) =>
        ensureUsagePeriods(owner, renewal),
      );
      expect(next.monthly).toMatchObject({ reserved: 1, importedReserved: 1 });
      await withUsageTransaction(db, f.user.id, (owner) =>
        confirmUsage(owner, claim.deliveryKey, claim.claimToken!, {
          gmailMessageId: "during-grace",
          sentAt: inGrace,
        }),
      );
      const old = await db.usagePeriod.findFirstOrThrow({
        where: { userId: f.user.id, id: initial.monthly.id },
      });
      const renewed = await db.usagePeriod.findFirstOrThrow({
        where: { userId: f.user.id, id: next.monthly.id },
      });
      expect(old).toMatchObject({ sent: 1, reserved: 0, importedSent: 0 });
      expect(renewed).toMatchObject({
        sent: 1,
        reserved: 0,
        importedSent: 1,
        importedReserved: 0,
      });
    });

    it("does not impose new caps for flag-off callers and isolates owners at both API and FK boundaries", async () => {
      const f = await setup(4),
        other = await setup();
      await withUsageTransaction(db, f.user.id, (owner) =>
        reserveUsage(owner, f.specs, f.items, false),
      );
      expect((await totals(f.user.id)).map((p) => p.reserved)).toEqual([4, 4]);
      await reserved(other);
      await expect(
        withUsageTransaction(db, other.user.id, (owner) =>
          releaseUsage(owner, f.items[0].deliveryKey, { kind: "UNSUBMITTED" }),
        ),
      ).rejects.toThrow("reservation unavailable");
      const otherDay = (await totals(other.user.id)).find(
        (p) => p.kind === "DAILY",
      )!;
      await expect(
        db.usageReservation.updateMany({
          where: { userId: f.user.id },
          data: { dailyPeriodId: otherDay.id },
        }),
      ).rejects.toMatchObject({ code: "P2003" });
      expect((await totals(other.user.id)).map((p) => p.reserved)).toEqual([
        1, 1,
      ]);
      // Permanent purge must deliberately remove accounting in FK-safe order.
      await withUsageTransaction(db, f.user.id, async ({ tx, userId }) => {
        await tx.usageReservation.deleteMany({ where: { userId } });
        await tx.usageImportEvidence.deleteMany({ where: { userId } });
        await tx.usagePeriod.deleteMany({ where: { userId } });
        await tx.campaign.deleteMany({ where: { userId } });
        await tx.user.delete({ where: { id: userId } });
      });
      expect(await totals(f.user.id)).toEqual([]);
      expect((await totals(other.user.id)).map((p) => p.reserved)).toEqual([
        1, 1,
      ]);
    });
